/* Fixed-work benchmark; files are generated by the pinned Python baseline. */
static double benchmark_clock(void) {
  struct timespec t;
  clock_gettime(CLOCK_MONOTONIC, &t);
  return t.tv_sec + t.tv_nsec / 1e9;
}
static void benchmark_time(const char *name, double start) {
  printf("{\"stage\":\"%s\",\"seconds\":%.6f}\n", name, benchmark_clock() - start);
  fflush(stdout);
}
static int benchmark_cancel(const char *phase, int done, int total, void *opaque) {
  (void)phase; (void)done; (void)total; (void)opaque;
  return 0;
}
static int benchmark(const char *package, const char *shaders, const char *dir, int replay) {
  char error[512] = {0}, name[64];
  int n;
  uint32_t *prefix = read_file(dir, "prefix.bin", &n);
  int count = n / 4;
  uint32_t *codec = read_file(dir, "codec.bin", &n);
  int frames = n / 4;
  float *noise = read_file(dir, "noise.bin", &n);
  float *latent = malloc(n), *logits = malloc(184704 * sizeof(float));
  double start = benchmark_clock();
  yue2_model *m = yue2_load(package, shaders, error, sizeof(error));
  if (!m || !latent || !logits || frames < 128) goto bad;
  benchmark_time("load", start);
  if (replay) {
    int prompt = 0;
    while (prompt < count && prefix[prompt] != 151847) prompt++;
    prompt++;
    if (prompt > count-2 || prefix[count-2] != 151848 || prefix[count-1] != 151851) goto bad;
    start = benchmark_clock();
    // Reserve the final context before AR, as the production generator does.
    if (yue2_synthesize(m,prefix,count,codec,frames,noise,8,latent,benchmark_cancel,NULL,error,sizeof(error)) || strcmp(error,"Cancelled")) goto bad;
    if (!yue2_forward(m,prefix,prompt,0,28,logits,error,sizeof(error))) goto bad;
    for (int i=prompt;i<count-2;i++)
      if (!yue2_forward(m,prefix+i,1,i,28,logits,error,sizeof(error))) goto bad;
    benchmark_time("plan",start);
    start = benchmark_clock();
    if (!yue2_forward(m,prefix+count-2,2,count-2,28,logits,error,sizeof(error))) goto bad;
    for (int i=0;i<frames-1;i++) {
      uint32_t token=codec[i]+151853;
      if (!yue2_forward(m,&token,1,count+i,28,logits,error,sizeof(error))) goto bad;
    }
    benchmark_time("semantic",start);
  }
  for (int trial = 0; !replay && trial < 2; trial++) {
    start = benchmark_clock();
    for (int base = 0; base < count; base += 128) {
      int rows = count-base < 128 ? count-base : 128;
      if (!yue2_forward(m,prefix+base,rows,base,28,base+rows==count?logits:NULL,error,sizeof(error))) goto bad;
    }
    snprintf(name,sizeof(name),"prefill-%d",trial); benchmark_time(name,start);yue2_print_timing(m);
    start = benchmark_clock();
    for (int i = 0; i < 128; i++) {
      uint32_t token = codec[i] + 151853;
      if (!yue2_forward(m,&token,1,count+i,28,logits,error,sizeof(error))) goto bad;
    }
    snprintf(name,sizeof(name),"ar128-%d",trial); benchmark_time(name,start);yue2_print_timing(m);
  }
  int maximum_steps = getenv("H3_YUE2_BENCH_MAX_STEPS") ? atoi(getenv("H3_YUE2_BENCH_MAX_STEPS")) : 32;
  for (int steps = 8; steps <= maximum_steps; steps *= 2) {
    if (!replay) yue2_reset_cache(m); // Cold microbenchmark; replay keeps the production AR cache.
    start = benchmark_clock();
    if (!yue2_synthesize(m,prefix,count,codec,frames,noise,steps,latent,progress,NULL,error,sizeof(error))) goto bad;
    snprintf(name,sizeof(name),"synthesis-%d",steps);benchmark_time(name,start);yue2_print_timing(m);
    snprintf(name,sizeof(name),"latent-%d",steps);write_file(dir,name,latent,frames*64*sizeof(float));
  }
  float *z = read_file(dir,"decode_input.bin",&n), *audio = NULL;
  int samples;
  start = benchmark_clock();
  if (!yue2_decode(m,z,frames,&audio,&samples,progress,NULL,error,sizeof(error))) goto bad;
  benchmark_time("decode",start);write_file(dir,"audio",audio,(size_t)samples*2*sizeof(float));
  free(z);free(audio);free(prefix);free(codec);free(noise);free(latent);free(logits);yue2_free(m);
  return 0;
bad:
  fprintf(stderr,"benchmark failed: %s\n",error);return 1;
}
